challenge.solution:
단어장 = {}
try:
    with open("단어장.txt") as 파일:
        for 줄 in 파일:
            칸 = 줄.strip().split(",")
            단어장[칸[0]] = 칸[1]
except FileNotFoundError:
    단어장 = {"사과": "apple", "바나나": "banana"}
    with open("단어장.txt", "w") as 파일:
        for 낱말 in 단어장:
            print(낱말, 단어장[낱말], sep=",", file=파일)
낱말 = input("낱말: ")
if 낱말 in 단어장:
    print(단어장[낱말])
else:
    print("모르는 낱말이에요")
